let lang='he', route='foryou', filter='all';
const bag={};
const fmt=n=>n.toLocaleString('en-US');
function pmedia(p){
  const svg=ICON[p.icon]||REPICON[p.icon]||REPICON.tools;
  if(!p.img) return svg;
  return `<span class="pfb">${svg}</span><img class="pimg" src="${p.img}" alt="${p.name||''}" loading="lazy" onerror="var f=this.previousElementSibling; if(f) f.classList.add('show'); this.remove();">`;
}
function catName(c){return c==='all'?T[lang].filter_all:T[lang]['cat_'+c];}

/* ---------- motion system ----------
   canHover gates every pointer-driven effect (mouse-tracking hero tilt, spotlight,
   magnetic buttons) to fine-pointer, no-reduced-motion contexts; touch and
   reduced-motion visitors get plain, instant UI. Reveal/counters use IntersectionObserver
   so they never block first paint. */
const canHover = matchMedia('(hover:hover) and (pointer:fine)').matches && !matchMedia('(prefers-reduced-motion:reduce)').matches;
const revealObserver = 'IntersectionObserver' in window ? new IntersectionObserver((entries)=>{
  entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('in-view'); revealObserver.unobserve(en.target); } });
},{threshold:.15,rootMargin:'0px 0px -8% 0px'}) : null;
function fmtCount(n,format){ return format==='k' ? (n/1000).toFixed(1)+'K' : Math.round(n).toLocaleString('en-US'); }
function animateCount(el){
  const target=parseFloat(el.dataset.countup), suffix=el.dataset.suffix||'', format=el.dataset.format||'';
  const start=performance.now(), dur=1200;
  function frame(t){
    const p=Math.min(1,(t-start)/dur), eased=1-Math.pow(1-p,3);
    el.textContent=fmtCount(target*eased,format)+suffix;
    if(p<1) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}
const counterObserver = 'IntersectionObserver' in window ? new IntersectionObserver((entries)=>{
  entries.forEach(en=>{ if(en.isIntersecting){ animateCount(en.target); counterObserver.unobserve(en.target); } });
},{threshold:.6}) : null;
function attachSpot(el){
  el.addEventListener('pointermove',e=>{
    const r=el.getBoundingClientRect();
    el.style.setProperty('--mx',((e.clientX-r.left)/r.width*100)+'%');
    el.style.setProperty('--my',((e.clientY-r.top)/r.height*100)+'%');
    el.classList.add('spot-active');
  });
  el.addEventListener('pointerleave',()=>el.classList.remove('spot-active'));
}
function attachMagnetic(el){
  el.addEventListener('pointermove',e=>{
    const r=el.getBoundingClientRect();
    const mx=(e.clientX-(r.left+r.width/2))*.25, my=(e.clientY-(r.top+r.height/2))*.35;
    el.style.transform=`translate(${mx}px, ${my}px)`;
  });
  el.addEventListener('pointerleave',()=>{ el.style.transform=''; });
}
function initMotionFor(root){
  if(!root) return;
  if(revealObserver) root.querySelectorAll('[data-reveal]').forEach(el=>revealObserver.observe(el));
  if(counterObserver) root.querySelectorAll('[data-countup]').forEach(el=>counterObserver.observe(el));
  if(canHover){
    root.querySelectorAll('.spot').forEach(attachSpot);
    root.querySelectorAll('.magnetic').forEach(attachMagnetic);
  }
}
function initHeroTilt(){
  if(!canHover) return;
  const stage=document.getElementById('heroStage'), device=document.getElementById('heroDevice');
  if(!stage||!device) return;
  stage.addEventListener('pointermove',e=>{
    const r=stage.getBoundingClientRect();
    const px=(e.clientX-r.left)/r.width-.5, py=(e.clientY-r.top)/r.height-.5;
    device.style.transform=`rotateY(${px*22}deg) rotateX(${py*-16}deg)`;
  });
  stage.addEventListener('pointerleave',()=>{ device.style.transform=''; });
}

function productCard(p,i){
  const tag=p.badge?`<span class="tag ${p.badge==='hot'?'hot':''}">${p.badge==='hot'?'HOT':T[lang].new}</span>`:'';
  const delay=Math.min(i||0,7)*.06;
  return `<article class="pcard" data-pid="${p.id}" data-reveal style="transition-delay:${delay}s">
    <div class="pcard-media">${tag}${pmedia(p)}</div>
    <div class="pcard-body">
      <span class="pcard-kind">${catName(p.cat)}</span>
      <span class="pcard-name">${p.name}</span>
      <div class="pcard-foot"><span class="price">${fmt(p.price)}</span>
        <button class="add" data-add="${p.id}" aria-label="${T[lang].add}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button></div>
    </div></article>`;
}
function renderArrivals(){
  const list=PRODUCTS.filter(p=>p.badge).concat(PRODUCTS.filter(p=>!p.badge)).slice(0,6);
  const el=document.getElementById('fy-arrivals');
  el.innerHTML=list.map(productCard).join('');
  initMotionFor(el);
}
function renderServices(){
  document.getElementById('fy-services').innerHTML=`
    <div class="feature-lg spot" data-reveal>
      <div class="fic">${NAVICON.speed}</div>
      <h3>${T[lang].fy_s1_h}</h3><p>${T[lang].fy_s1_p}</p>
    </div>
    <div class="feature-sm" data-reveal style="transition-delay:.1s">
      <div class="fic">${NAVICON.swap}</div>
      <h3>${T[lang].fy_s2_h}</h3><p>${T[lang].fy_s2_p}</p>
    </div>
    <div class="feature-sm" data-reveal style="transition-delay:.2s">
      <div class="fic">${NAVICON.truck}</div>
      <h3>${T[lang].fy_s3_h}</h3><p>${T[lang].fy_s3_p}</p>
    </div>`;
  initMotionFor(document.getElementById('fy-services'));
}
function renderChips(){
  document.getElementById('chips').innerHTML=FILTERS.map(f=>`<button class="chip ${f===filter?'on':''}" data-filter="${f}">${catName(f)}</button>`).join('');
}
function renderProducts(){
  const list=filter==='all'?PRODUCTS:PRODUCTS.filter(p=>p.cat===filter);
  const el=document.getElementById('grid');
  el.innerHTML=list.map(productCard).join('');
  initMotionFor(el);
}

/* ---------- product detail page ---------- */
let pdpId=null, pdpColorIdx=0, pdpVariantIdx=0, pdpQty=1;
function openProduct(id){
  pdpId=Number(id);
  const p=PRODUCTS.find(x=>x.id===pdpId);
  if(!p) return;
  pdpColorIdx=0; pdpVariantIdx=0; pdpQty=1;
  go('product');
  renderProductPage();
}
function pdpPrice(p){
  const delta=p.storage?p.storage[pdpVariantIdx].delta:0;
  return p.price+delta;
}
function renderProductPage(){
  const p=PRODUCTS.find(x=>x.id===pdpId);
  const box=document.getElementById('pdp-body');
  if(!p){ box.innerHTML=''; return; }
  const variantLabelKey='pdp_'+(p.variant2Label||'storage');
  const colorsHtml=p.colors?`<div class="pdp-section"><div class="pdp-label">${T[lang].pdp_color} <span class="val">${p.colors[pdpColorIdx].name}</span></div>
    <div class="swatches">${p.colors.map((c,i)=>`<button class="swatch ${i===pdpColorIdx?'on':''}" data-color-idx="${i}" style="background:${c.hex}" aria-label="${c.name}"></button>`).join('')}</div></div>`:'';
  const storageHtml=p.storage?`<div class="pdp-section"><div class="pdp-label">${T[lang][variantLabelKey]}</div>
    <div class="pills">${p.storage.map((s,i)=>`<button class="pill-opt ${i===pdpVariantIdx?'on':''}" data-variant-idx="${i}">${s.label}</button>`).join('')}</div></div>`:'';
  const price=pdpPrice(p);
  const related=PRODUCTS.filter(x=>x.cat===p.cat && x.id!==p.id).slice(0,4);
  const relatedHtml=related.length?`<div class="pdp-more">
    <div class="section-head" data-reveal><div><h2 class="h2">${T[lang].pdp_more} ${catName(p.cat)}</h2></div></div>
    <div class="row">${related.map(productCard).join('')}</div></div>`:'';
  box.innerHTML=`
    <button class="pdp-back" data-route="products"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg>${T[lang].pdp_back}</button>
    <div class="pdp-grid">
      <div class="pdp-gallery">${pmedia(p)}</div>
      <div>
        <div class="pdp-kind">${catName(p.cat)}</div>
        <h1 class="pdp-name">${p.name}</h1>
        <div class="pdp-price">₪${fmt(price)}</div>
        ${p.desc?`<p class="pdp-desc">${p.desc[lang]}</p>`:''}
        ${colorsHtml}
        ${storageHtml}
        <div class="pdp-section">
          <div class="pdp-label">${T[lang].pdp_qty}</div>
          <div class="qty"><button data-pdp-dec>−</button><span>${pdpQty}</span><button data-pdp-inc>+</button></div>
        </div>
        <div class="pdp-cta">
          <button class="btn btn-primary" data-pdp-add>${T[lang].pdp_add}</button>
        </div>
      </div>
    </div>
    ${relatedHtml}`;
  initMotionFor(box);
}
function renderSteps(){
  const el=document.getElementById('steps');
  el.innerHTML=[1,2,3].map(n=>`<div class="process-row" data-reveal style="transition-delay:${(n-1)*.08}s"><div class="process-n">0${n}</div><div class="process-body"><h3>${T[lang]['step'+n+'_h']}</h3><p>${T[lang]['step'+n+'_p']}</p></div></div>`).join('');
  initMotionFor(el);
}
function renderRepairs(){
  const el=document.getElementById('rlist');
  el.innerHTML=REPAIRS.map((r,i)=>{
    const ic=REPICON[r.ic]||ICON[r.ic]||REPICON.tools;
    return `<div class="prow" data-reveal style="transition-delay:${Math.min(i,6)*.05}s"><div class="ric">${ic}</div>
      <div class="rinfo"><div class="rn">${T[lang]['rep_'+r.id]}</div><div class="rp">${T[lang].rp_from} ₪${fmt(r.price)}</div></div>
      <button class="add" data-book="${r.id}" aria-label="${T[lang].rp_book}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button></div>`;}).join('');
  initMotionFor(el);
}
function renderFaq(){
  const items=[1,2,3,4].map(n=>`<div class="faq-item"><button class="faq-q">${T[lang]['faq'+n+'_q']}<svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg></button><div class="faq-a"><div><p>${T[lang]['faq'+n+'_a']}</p></div></div></div>`).join('');
  document.getElementById('faq').innerHTML=items;
}
function lookup(it){ return it.type==='product'?PRODUCTS.find(p=>p.id==it.id):REPAIRS.find(r=>r.id==it.id); }
function unitPrice(it){ const o=lookup(it); return o.price+(it.delta||0); }
function itemName(it){
  const base=it.type==='product'?lookup(it).name:T[lang]['rep_'+it.id];
  const bits=[it.color,it.variant].filter(Boolean);
  return bits.length? base+' · '+bits.join(' · ') : base;
}
function bagCount(){ return Object.values(bag).reduce((s,i)=>s+i.qty,0); }
function updateBagBadges(){
  const n=bagCount(); const c=document.getElementById('bagCount'); c.textContent=n; c.classList.toggle('show',n>0);
  const m=document.getElementById('mmBadge'); m.textContent=n; m.classList.toggle('show',n>0);
}
function renderBag(){
  const items=Object.values(bag), box=document.getElementById('bag-body');
  if(!items.length){ box.innerHTML=`<div class="empty"><h3>${T[lang].bag_empty_h}</h3><p>${T[lang].bag_empty_p}</p><br><button class="btn btn-primary" data-route="products">${T[lang].bag_empty_cta}</button></div>`; updateBagBadges(); return; }
  let total=0;
  const rows=items.map(it=>{ const o=lookup(it); const up=unitPrice(it); const price=up*it.qty; total+=price;
    return `<div class="bi"><div class="bi-media">${pmedia(it.type==='product'?o:{icon:REPAIRS.find(r=>r.id==it.id).ic})}</div>
      <div class="bi-info"><span class="bi-tag ${it.type}">${it.type==='product'?T[lang].tag_product:T[lang].tag_repair}</span>
        <div class="bi-n">${itemName(it)}</div><div class="bi-p">₪${fmt(up)}</div>
        <div class="qty"><button data-dec="${it.key}">−</button><span>${it.qty}</span><button data-inc="${it.key}">+</button></div></div>
      <button class="bi-remove" data-remove="${it.key}">${T[lang].bag_remove}</button></div>`;}).join('');
  box.innerHTML=rows+`<div class="bag-summary">
      <div class="bag-line"><span>${T[lang].bag_subtotal}</span><span>₪${fmt(total)}</span></div>
      <div class="bag-line"><span>${T[lang].bag_ship}</span><span>${T[lang].bag_ship_v}</span></div>
      <div class="bag-total"><span>${T[lang].bag_total}</span><span>₪${fmt(total)}</span></div>
      <button class="btn btn-primary" id="checkout">${T[lang].bag_checkout}</button></div>`;
  updateBagBadges();
}
function addItem(type,id,opts){
  opts=opts||{};
  const vKey=opts.color||opts.variant?':'+(opts.color||'')+'|'+(opts.variant||''):'';
  const k=type+':'+id+vKey;
  bag[k]=bag[k]||{type,id,qty:0,key:k,color:opts.color||null,variant:opts.variant||null,delta:opts.delta||0};
  bag[k].qty+=opts.qty||1;
  updateBagBadges();
  if(route==='bag')renderBag();
}

function applyText(){
  document.querySelectorAll('[data-t]').forEach(el=>{const v=T[lang][el.getAttribute('data-t')]; if(v!==undefined) el.textContent=v;});
  document.querySelectorAll('[data-ph]').forEach(el=>{const v=T[lang][el.getAttribute('data-ph')]; if(v!==undefined) el.placeholder=v;});
}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),1900);}

function go(name){
  route=name;
  document.querySelectorAll('.page').forEach(p=>p.hidden = p.id!=='p-'+name);
  document.querySelectorAll('.nav-links a').forEach(a=>a.classList.toggle('active',a.dataset.route===name||(name==='product'&&a.dataset.route==='products')));
  document.querySelector('.bag-btn').classList.toggle('active',name==='bag');
  if(name==='products'){renderChips();renderProducts();}
  if(name==='repairs'){renderSteps();renderRepairs();}
  if(name==='bag')renderBag();
  mobileMenu.classList.remove('open');
  document.getElementById('nav').classList.toggle('scrolled',scrollY>10);
  window.scrollTo({top:0,behavior:'instant'});
}

function setLang(l){
  lang=l; document.documentElement.lang=l; document.documentElement.dir=T[l].dir;
  document.querySelectorAll('.lang button').forEach(b=>b.classList.toggle('on',b.dataset.l===l));
  applyText(); renderArrivals(); renderServices(); renderFaq();
  if(route==='products'){renderChips();renderProducts();}
  if(route==='repairs'){renderSteps();renderRepairs();}
  if(route==='bag')renderBag();
  if(route==='product')renderProductPage();
  updateBagBadges();
}

/* events */
document.querySelectorAll('.lang').forEach(g=>g.addEventListener('click',e=>{const b=e.target.closest('[data-l]');if(b)setLang(b.dataset.l);}));
const menuToggle=document.getElementById('menuToggle'),mobileMenu=document.getElementById('mobileMenu');
menuToggle.addEventListener('click',()=>{const o=mobileMenu.classList.toggle('open');document.getElementById('nav').classList.toggle('scrolled',o||scrollY>10);});
document.addEventListener('click',e=>{
  const rt=e.target.closest('[data-route]'); if(rt){go(rt.dataset.route); return;}
  const add=e.target.closest('[data-add]'); if(add){addItem('product',add.dataset.add);toast(T[lang].added);return;}
  const bk=e.target.closest('[data-book]'); if(bk){addItem('repair',bk.dataset.book);toast(T[lang].added_rep);return;}
  const inc=e.target.closest('[data-inc]'); if(inc){bag[inc.dataset.inc].qty++;renderBag();return;}
  const dec=e.target.closest('[data-dec]'); if(dec){const k=dec.dataset.dec;bag[k].qty--;if(bag[k].qty<=0)delete bag[k];renderBag();return;}
  const rm=e.target.closest('[data-remove]'); if(rm){delete bag[rm.dataset.remove];renderBag();return;}
  const chip=e.target.closest('[data-filter]'); if(chip){filter=chip.dataset.filter;renderChips();renderProducts();return;}
  const faq=e.target.closest('.faq-q'); if(faq){faq.parentElement.classList.toggle('open');return;}
  const pcard=e.target.closest('.pcard[data-pid]'); if(pcard){openProduct(pcard.dataset.pid);return;}
  const colorBtn=e.target.closest('[data-color-idx]'); if(colorBtn){pdpColorIdx=Number(colorBtn.dataset.colorIdx);renderProductPage();return;}
  const variantBtn=e.target.closest('[data-variant-idx]'); if(variantBtn){pdpVariantIdx=Number(variantBtn.dataset.variantIdx);renderProductPage();return;}
  if(e.target.closest('[data-pdp-inc]')){pdpQty++;renderProductPage();return;}
  if(e.target.closest('[data-pdp-dec]')){pdpQty=Math.max(1,pdpQty-1);renderProductPage();return;}
  if(e.target.closest('[data-pdp-add]')){
    const p=PRODUCTS.find(x=>x.id===pdpId);
    const color=p.colors?p.colors[pdpColorIdx].name:null;
    const variant=p.storage?p.storage[pdpVariantIdx].label:null;
    const delta=p.storage?p.storage[pdpVariantIdx].delta:0;
    addItem('product',p.id,{color,variant,delta,qty:pdpQty});
    toast(T[lang].added);
    return;
  }
  if(e.target.id==='checkout'){modal.classList.add('open');return;}
  if(e.target.id==='f-send'){toast(T[lang].form_sent);['f-name','f-contact','f-msg'].forEach(i=>document.getElementById(i).value='');return;}
});
const modal=document.getElementById('modal');
document.getElementById('modalClose').addEventListener('click',()=>modal.classList.remove('open'));
modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open');});
const nav=document.getElementById('nav');
addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>10||mobileMenu.classList.contains('open')));

/* init */
document.querySelectorAll('.brand-logo').forEach(el=>el.src=LOGO);
setLang('he');
renderArrivals(); renderServices(); renderFaq();
go('foryou');
initHeroTilt();
initMotionFor(document);
